private const val TAG = "MonsteraRuntime"
private const val RAW_ONE = 65536f
private const val TAP_SLOP_PX = 12f

private fun hexColor(hex: String): Color = Color(0xFF000000 or hex.removePrefix("#").toLong(16))

/**
 * Shell: measures frame time, turns touches into input events, draws the world.
 * It never steps the simulation itself; every tick goes through [GameLoop] (contract section 1).
 * Floating point here is for display only.
 */
@Composable
fun GameScreen(spec: MonsteraSpec, verified: Boolean) {
    val palette = spec.game.palette
    val cfg = GeneratedRuntimeConfig.config
    // The session seed is chosen outside the core; it is logged so a session can be replayed.
    val seed = remember { System.currentTimeMillis() and 0x1FFFFFFFFFFFFFL }
    val loop = remember { GameLoop(World(cfg, seed.toULong()), GeneratedRuntimeConfig.TICK_RATE, GeneratedRuntimeConfig.MAX_TICKS_PER_FRAME) }
    var frames by remember { mutableLongStateOf(0L) }  // read by the Canvas so it redraws every frame
    var viewSize by remember { mutableStateOf(IntSize.Zero) }
    val worldW = cfg.worldWidth / RAW_ONE
    val worldH = cfg.worldHeight / RAW_ONE
    fun pixelsPerUnit(): Float =
        if (viewSize.width == 0) 1f else minOf(viewSize.width / worldW, viewSize.height / worldH)

    LaunchedEffect(loop) {
        var last = 0L
        var logged = false
        while (true) {
            withFrameNanos { now ->
                loop.frame(if (last == 0L) 0L else now - last)
                last = now
                frames++
                if (!logged && loop.world.tick >= 60u) {
                    logged = true
                    Log.i(TAG, "runtime ticks=${loop.world.tick} hash=${loop.world.stateHash().toString(16).padStart(16, '0')} seed=$seed")
                }
            }
        }
    }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .onSizeChanged { viewSize = it }
            .semantics { contentDescription = "Game view" }
            .pointerInput(loop) {
                detectTapGestures(
                    onPress = {
                        loop.submit(InputEvent(InputType.PRESS))
                        tryAwaitRelease()
                        loop.submit(InputEvent(InputType.RELEASE))
                    },
                    onTap = { loop.submit(InputEvent(InputType.TAP)) },
                )
            }
            .pointerInput(loop, spec.game.input.scheme) {
                var total = Offset.Zero
                detectDragGestures(
                    onDragStart = { total = Offset.Zero },
                    onDragEnd = {
                        if (spec.game.input.scheme == InputScheme.SWIPE && maxOf(abs(total.x), abs(total.y)) > TAP_SLOP_PX) {
                            val dir = if (abs(total.x) > abs(total.y)) {
                                if (total.x > 0f) Direction.RIGHT else Direction.LEFT
                            } else {
                                if (total.y > 0f) Direction.DOWN else Direction.UP
                            }
                            loop.submit(InputEvent(InputType.SWIPE, dir = dir))
                        }
                    },
                ) { _, amount ->
                    total += amount
                    if (spec.game.input.scheme != InputScheme.SWIPE) {
                        val s = pixelsPerUnit()
                        loop.submit(InputEvent(InputType.DRAG, (amount.x / s * RAW_ONE).roundToLong(), (amount.y / s * RAW_ONE).roundToLong()))
                    }
                }
            },
    ) {
        Canvas(modifier = Modifier.fillMaxSize()) {
            check(frames >= 0L)  // reading the state subscribes this draw scope to every frame
            drawRect(hexColor(palette.background))
            val scale = minOf(size.width / worldW, size.height / worldH)
            val worldSize = Size(worldW * scale, worldH * scale)
            val origin = Offset((size.width - worldSize.width) / 2f, (size.height - worldSize.height) / 2f)
            drawRect(hexColor(palette.primary), topLeft = origin, size = worldSize, style = Stroke(width = 4f))
            val alpha = loop.alpha / RAW_ONE
            for (e in loop.world.snapshot()) {
                val k = cfg.kinds[e.kind]
                // Interpolated for display only; the simulation state is never changed by drawing.
                val x = (e.x + e.vx * alpha) / RAW_ONE
                val y = (e.y + e.vy * alpha) / RAW_ONE
                drawRect(
                    color = if (e.kind % 2 == 0) hexColor(palette.primary) else hexColor(palette.accent),
                    topLeft = Offset(origin.x + x * scale, origin.y + y * scale),
                    size = Size(k.width / RAW_ONE * scale, k.height / RAW_ONE * scale),
                )
            }
        }
        Column(
            modifier = Modifier.align(Alignment.TopCenter).padding(top = 64.dp),
            horizontalAlignment = Alignment.CenterHorizontally,
        ) {
            Text(spec.project.displayName, color = Color.White, style = MaterialTheme.typography.headlineMedium)
            Text("${spec.game.genre.value} | ${spec.game.orientation.value} | ${spec.game.simulation.tickRate} ticks/s", color = Color.White)
            Text("spec ${GeneratedSpec.SHA256.take(12)} " + if (verified) "verified" else "MISMATCH", color = Color.White)
            Text(
                frames.let { "score ${loop.world.score}  lives ${loop.world.lives}" + if (loop.world.ended) "  game over" else "" },
                color = Color.White,
            )
        }
    }
}
